/* ---------- 健康科普 ---------- */
const ARTICLES = [
  { id: 1, cat: '心理健康', icon: '🧠', cover: '#E8F2EC', title: '总是内耗？试试这 5 个"停止"信号', abs: '精神内耗正在悄悄消耗你的能量。识别并停止这 5 种思维模式，把注意力还给当下。', author: '项目组整理 · 待专业审校', date: '2026-01-18', reads: '演示', like: 0,
    body: '<p>很多人表面安静，内心却上演着一场没有观众的辩论赛——反复咀嚼一句话、一个眼神、一次失败。这就是"精神内耗"。</p><h3>一、停止"过度反刍"</h3><p>反复回想已经发生的事，并不会改变结果。心理学上称为"反刍思维"，它会放大焦虑。试着把"如果当初…"换成"现在我可以…"。</p><h3>二、停止"灾难化想象"</h3><p>事情还没发生，大脑已经预演了最坏结局。你可以问自己：最坏情况发生的概率有多大？我真正能承受吗？往往你会发现，恐惧被夸大了。</p><h3>三、停止"讨好所有人"</h3><p>被所有人喜欢是一个不可能完成的 KPI。把注意力放在少数真正重要的人身上，你会轻松很多。</p><h3>四、停止"和他人比较"</h3><p>每个人的时区不同。别人的高光时刻，不代表你的黯淡。关注自己的成长曲线，而非别人的成绩单。</p><h3>五、停止"追求完美"</h3><p>完美是行动的敌人。允许自己先完成、再完美，你会发现世界没有因此崩塌。</p><p>如果这些内耗已经严重影响你的生活，欢迎预约专业咨询师，我们陪你一起梳理。</p>' },
  { id: 2, cat: '心理健康', icon: '😌', cover: '#F0EDF7', title: '正念呼吸：3 分钟快速平静下来的方法', abs: '焦虑来袭时，你的呼吸就是随身携带的练习工具。跟着步骤，学习腹式呼吸与身体扫描。', author: '项目组整理 · 待专业审校', date: '2026-01-12', reads: '演示', like: 0,
    body: '<p>当压力来袭，身体最先给出信号：心跳加速、呼吸变浅、肩膀紧绷。正念呼吸能快速激活副交感神经，帮你"刹车"。</p><h3>腹式呼吸四步法</h3><p>① 用鼻子缓慢吸气，数 4 秒；② 屏住呼吸，数 4 秒；③ 用嘴缓缓呼气，数 6 秒；④ 重复 5–10 轮。</p><h3>身体扫描</h3><p>闭上眼睛，从头顶开始，把注意力依次带到眉心、下巴、肩膀、胸口、腹部……每到一个部位，感受它的紧张，然后主动放松它。</p><h3>什么时候用？</h3><p>开会前、失眠时、情绪激动时，随时随地都可以给自己 3 分钟。</p>' },
  { id: 3, cat: '睡眠健康', icon: '🛏️', cover: '#E8F2EC', title: '熬夜成瘾？改善睡眠的 7 个习惯', abs: '持续睡眠不足可能影响情绪和日间状态。7 个可执行的小习惯，帮助建立睡眠节律。', author: '项目组整理 · 待专业审校', date: '2026-01-08', reads: '演示', like: 0,
    body: '<p>睡眠是心理健康的基石。长期睡眠不足会显著增加焦虑、抑郁的风险。</p><h3>7 个习惯</h3><p>① 固定起床时间，比固定入睡时间更重要；② 睡前 1 小时远离屏幕蓝光；③ 卧室保持凉爽、黑暗；④ 下午 2 点后不喝咖啡；⑤ 白天适度运动，但睡前 3 小时避免剧烈运动；⑥ 建立睡前仪式：温水澡、阅读、轻音乐；⑦ 睡不着就起床，别在床上"硬熬"。</p><p>如果长期失眠，建议进行专业评估，排除潜在的身心因素。</p>' },
  { id: 4, cat: '压力管理', icon: '🌊', cover: '#FBF3E0', title: '压力不全是坏事：如何理解压力反应', abs: '压力反应可能同时带来负担和行动信号，可以尝试用更可控的方式理解当前挑战。', author: '项目组整理 · 待专业审校', date: '2026-01-05', reads: '演示', like: 0,
    body: '<p>心理学家发现，压力本身不致命，真正有害的是"压力有害"这个信念。</p><h3>重新解释压力</h3><p>心跳加速、手心出汗，其实是你身体在为挑战"蓄力"。告诉自己：这是我的身体在帮我准备，不是要击垮我。</p><h3>挑战 vs 威胁</h3><p>把任务看成"我可以应对的挑战"而非"可能压垮我的威胁"，压力反应会从消耗转向赋能。</p><h3>给自己留缓冲</h3><p>长期高压需要出口：运动、倾诉、专业支持，都是有效的减压阀。</p>' },
  { id: 5, cat: '营养健康', icon: '🥗', cover: '#E8F2EC', title: '规律饮食与情绪健康', abs: '饮食、睡眠和情绪之间存在关联，均衡饮食可以作为健康生活方式的一部分。', author: '项目组整理 · 待专业审校', date: '2026-01-02', reads: '演示', like: 0,
    body: '<p>肠道菌群与大脑通过"肠脑轴"双向沟通，你吃的每一口都在影响情绪。</p><h3>5 类关键营养素</h3><p>① Omega-3（深海鱼、核桃）：抗炎、稳定情绪；② 色氨酸（牛奶、香蕉、鸡肉）：合成血清素的前体；③ B 族维生素（全谷物、绿叶菜）：神经系统能量代谢；④ 镁（坚果、深绿蔬菜）：放松神经；⑤ 益生菌（酸奶、发酵食物）：维护肠道菌群平衡。</p><p>均衡饮食 + 规律进食，是性价比最高的情绪投资。</p>' },
  { id: 6, cat: '运动健身', icon: '🏃', cover: '#F0EDF7', title: '从可坚持的运动开始照顾情绪', abs: '适度运动可能帮助改善睡眠和情绪状态，重点是选择适合自己的强度与节奏。', author: '项目组整理 · 待专业审校', date: '2025-12-28', reads: '演示', like: 0,
    body: '<p>大量研究表明，规律运动对轻中度焦虑、抑郁的改善效果，可与部分药物、心理治疗相当。</p><h3>为什么有效？</h3><p>运动促进内啡肽、多巴胺分泌，改善睡眠，提升自我效能感——"我能做到"的掌控感，是对抗焦虑的利器。</p><h3>怎么开始？</h3><p>不必追求强度。快走、慢跑、瑜伽、骑行，每天 20–30 分钟，贵在坚持。从"最小可坚持"开始，比一次过度运动更有效。</p>' },
  { id: 7, cat: '疾病预防', icon: '🛡️', cover: '#FBF3E0', title: '情绪低落时，什么时候需要专业帮助？', abs: '持续时间、生活影响和安全风险都是判断是否需要寻求专业帮助的重要信号。', author: '项目组整理 · 待专业审校', date: '2025-12-22', reads: '演示', like: 0,
    body: '<p>情绪低落是正常的情绪波动，抑郁症则是一种需要专业干预的疾病。两者有本质区别。</p><h3>关键区分</h3><p>① 持续时间：抑郁症的核心症状持续 ≥ 2 周；② 严重程度：明显影响学习、工作、社交；③ 是否伴随躯体症状：食欲、睡眠、精力显著改变；④ 是否有自伤念头。</p><h3>该怎么做？</h3><p>如果你或身边的人符合上述特征，请使用本 App 的 PHQ-9 量表进行初筛，并尽快寻求专业帮助。早期干预效果最佳。</p>' }
];

